        <tbody><tr><td>0.35 × 8 = 2.80</td><td>2</td></tr><tr><td>0.80 × 8 = 6.40</td><td>6</td></tr><tr><td>0.40 × 8 = 3.20</td><td>3</td></tr><tr><td>0.20 × 8 = 1.60</td><td>1</td></tr></tbody>
